/**
 * Factory findings triage tests (voicebox-beads-h1u0).
 *
 * The fixtures in `tests/fixtures/factory-reports/` were generated by the factory's OWN renderer
 * (`lib/findings.py:_render_delta_report`), not written by hand — a hand-written fixture would
 * only prove the parser agrees with the test author's idea of the format.
 *
 * The tests are pure: no network, no model, no real `gh`, no real `bd`. Both tools are stubbed
 * as executable shell scripts prepended to PATH, logging one line per invocation with newlines
 * flattened.
 */

import test from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import {
  chmodSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { homedir, tmpdir } from "node:os";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import {
  BEAD_EXTERNAL_REF_PREFIX,
  CREDENTIAL_AGENTS,
  CREDENTIAL_RULE_HINTS,
  EMBARGOED_SEVERITIES,
  GENERIC_REMEDIATION,
  IDENTITY_CRITICAL_AGENTS,
  PUBLICATION_DECLARATION,
  STATION_CLASSES,
  VALID_SEVERITIES,
  WITHHELD_NOTE,
  agentFromReportName,
  beadForPromotion,
  buildIssue,
  buildPlan,
  chooseLabels,
  computeFingerprint,
  existingBeadFingerprints,
  existingIssues,
  isCredentialFinding,
  isInside,
  isIssueDuplicate,
  knownLabels,
  markerFor,
  maskText,
  normalizePath,
  normalizeText,
  parseBadge,
  parseMarkers,
  parseReport,
  priorityFor,
  privateRootFromEnv,
  readIssue,
  resolveReportPath,
  routeFinding,
  sanitizeFinding,
  suggestsFunctionalityChange,
} from "../scripts/factory-triage.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");
const SCRIPT = join(ROOT, "scripts", "factory-triage.mjs");
const FIXTURES = join(HERE, "fixtures", "factory-reports");

const fixture = (name) => readFileSync(join(FIXTURES, name), "utf8");
const parseFixture = (name, agent) => parseReport(fixture(name), { agent });

/** Run the CLI in a private temp dir, with stub `gh` and `bd` on PATH. */
function runCli({ args, reports = {}, stubGh = null, stubBd = null, cwd = null, env = {} }) {
  const box = mkdtempSync(join(tmpdir(), "factory-triage-test-"));
  const privateDir = join(box, "private");
  mkdirSync(privateDir, { recursive: true });
  for (const [name, contents] of Object.entries(reports)) {
    writeFileSync(join(privateDir, name), contents);
  }
  const bin = join(box, "bin");
  mkdirSync(bin, { recursive: true });
  const ghLogFile = join(box, "gh-calls.log");
  const bdLogFile = join(box, "bd-calls.log");

  const defaultStubGh = `case "$1" in
    issue)
      case "$2" in
        list) echo '[]' ;;
        create) echo "https://github.com/owner/voicebox/issues/100" ;;
        view) cat << 'EOF'
{"number": 100, "state": "OPEN", "title": "stub", "body": "<!-- factory-fingerprint: 0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef -->\\n<!-- factory-station: qa-station -->\\n<!-- factory-severity: medium -->\\n<!-- factory-state: new -->\\n**Rule**: \`flake-instrumentation\`", "comments": []}
EOF
        ;;
        comment) echo "https://github.com/owner/voicebox/issues/100#issuecomment-1" ;;
        *) echo "unknown issue subcmd: $2" >&2; exit 1 ;;
      esac
      ;;
    label)
      case "$2" in
        list) echo '[{"name":"bug"},{"name":"enhancement"},{"name":"documentation"},{"name":"accessibility"},{"name":"human-review"}]' ;;
        *) echo "unknown label subcmd: $2" >&2; exit 1 ;;
      esac
      ;;
    *) echo "unknown gh cmd: $1" >&2; exit 1 ;;
  esac`;

  const ghScript = `#!/bin/sh
printf '%s\\n' "$*" | tr '\\n' ' ' >> ${ghLogFile}
printf '\\n' >> ${ghLogFile}
${stubGh ?? defaultStubGh}
`;
  writeFileSync(join(bin, "gh"), ghScript);
  chmodSync(join(bin, "gh"), 0o755);

  const defaultStubBd = `case "$1" in
    list) echo '[]' ;;
    create) echo "voicebox-beads-stub1" ;;
    update) echo "updated" ;;
    comment) echo "commented" ;;
    *) echo "unknown bd cmd: $1" >&2; exit 1 ;;
  esac`;

  const bdScript = `#!/bin/sh
printf '%s\\n' "$*" | tr '\\n' ' ' >> ${bdLogFile}
printf '\\n' >> ${bdLogFile}
${stubBd ?? defaultStubBd}
`;
  writeFileSync(join(bin, "bd"), bdScript);
  chmodSync(join(bin, "bd"), 0o755);

  const repo = cwd ?? join(box, "repo");
  mkdirSync(repo, { recursive: true });

  const resolvedArgs = args.map((arg) => (arg === "%PRIVATE%" ? privateDir : arg));
  const childEnv = {
    ...process.env,
    PATH: `${bin}:${process.env.PATH}`,
    VOICEBOX_FACTORY_PRIVATE_DIR: privateDir,
    VOICEBOX_FACTORY_REPO: "owner/voicebox",
    ...env,
  };
  if ("VOICEBOX_FACTORY_REPO" in env && (env.VOICEBOX_FACTORY_REPO === null || env.VOICEBOX_FACTORY_REPO === undefined)) {
    delete childEnv.VOICEBOX_FACTORY_REPO;
  }

  const res = spawnSync(process.execPath, [SCRIPT, ...resolvedArgs], {
    cwd: repo,
    encoding: "utf8",
    timeout: 30000,
    env: childEnv,
  });

  return {
    ...res,
    box,
    repo,
    privateDir,
    ghCalls: existsSync(ghLogFile) ? readFileSync(ghLogFile, "utf8").trim().split("\n").filter(Boolean) : [],
    bdCalls: existsSync(bdLogFile) ? readFileSync(bdLogFile, "utf8").trim().split("\n").filter(Boolean) : [],
  };
}

// ---------------------------------------------------------------------------------------------
// 1. Mirrored policy constants
// ---------------------------------------------------------------------------------------------

test("mirrored policy constants match the factory's published values", () => {
  assert.deepEqual(
    [...IDENTITY_CRITICAL_AGENTS].sort(),
    ["secret-scan", "threat-model", "vuln-discovery", "vuln-triage", "vuln-verify"],
  );
  assert.deepEqual([...CREDENTIAL_AGENTS], ["secret-scan"]);
  assert.deepEqual([...CREDENTIAL_RULE_HINTS], ["key", "secret", "token", "credential", "password", "private"]);
  assert.ok(Object.isFrozen(CREDENTIAL_RULE_HINTS));
  assert.deepEqual([...VALID_SEVERITIES], ["critical", "high", "medium", "low", "info"]);
  assert.ok(Object.isFrozen(VALID_SEVERITIES));
  assert.deepEqual([...EMBARGOED_SEVERITIES].sort(), ["critical", "high"]);
  assert.equal(BEAD_EXTERNAL_REF_PREFIX, "factory:");
  assert.ok(typeof PUBLICATION_DECLARATION === "string" && PUBLICATION_DECLARATION.length > 50);
  assert.ok(typeof WITHHELD_NOTE === "string" && WITHHELD_NOTE.length > 20);
  assert.ok(typeof GENERIC_REMEDIATION === "string" && GENERIC_REMEDIATION.length > 20);

  // 22 stations from `factory list`, grouped into 6 classes
  assert.equal(Object.keys(STATION_CLASSES).length, 22);
  const allowedClasses = new Set(["security", "quality", "docs", "ux", "perf", "ops"]);
  for (const [station, className] of Object.entries(STATION_CLASSES)) {
    assert.match(station, /^[a-z0-9-]+$/);
    assert.ok(allowedClasses.has(className), `${station} has unexpected class ${className}`);
  }

  // idle and unknown stations are absent from all policy sets
  assert.equal(IDENTITY_CRITICAL_AGENTS.has("idle"), false);
  assert.equal(IDENTITY_CRITICAL_AGENTS.has("unknown"), false);
  assert.equal(CREDENTIAL_AGENTS.has("idle"), false);
  assert.equal(CREDENTIAL_AGENTS.has("unknown"), false);
  assert.equal(STATION_CLASSES["idle"], undefined);
  assert.equal(STATION_CLASSES["unknown"], undefined);
});

// ---------------------------------------------------------------------------------------------
// 2. computeFingerprint: mirrors lib/findings.py
// ---------------------------------------------------------------------------------------------

test("computeFingerprint reproduces the factory's fingerprints for every verifiable real fixture", () => {
  let verifiedCount = 0;
  for (const name of readdirSync(FIXTURES).filter((n) => n.endsWith("-delta.md"))) {
    const agent = agentFromReportName(name);
    const report = parseFixture(name, agent);
    for (const finding of report.findings) {
      if (finding.identitySource === "unverifiable") {
        // Reduced/step-summary fixture (e.g. vuln-discovery) carries no snippet line
        continue;
      }
      assert.equal(
        finding.identitySource,
        "recomputed-and-verified",
        `${name}: recomputed fingerprint ${finding.fingerprint} does not match prefix ${finding.fingerprintFromReport}`,
      );
      assert.ok(
        finding.fingerprint.startsWith(finding.fingerprintFromReport),
        `${name}: ${finding.fingerprint} does not start with report prefix ${finding.fingerprintFromReport}`,
      );
      verifiedCount += 1;
    }
  }
  assert.ok(verifiedCount >= 5, `expected to verify >= 5 real fixture findings, verified ${verifiedCount}`);
});

test("computeFingerprint normalizes path separators, leading ./, and whitespace", () => {
  const a = computeFingerprint({
    agent: "qa-station",
    ruleId: "flake-test",
    path: "./tests\\unit\\sub\\test.ts",
    snippet: "  const  x   =  await  foo( ); \n\t ",
  });
  const b = computeFingerprint({
    agent: "qa-station",
    ruleId: "flake-test",
    path: "tests/unit/sub/test.ts",
    snippet: "const x = await foo( );",
  });
  assert.equal(a, b);
  assert.equal(normalizePath(".\\foo\\bar/baz.js"), "foo/bar/baz.js");
  assert.equal(normalizePath("///root/path"), "root/path");
  assert.equal(normalizePath(null), "");
  assert.equal(normalizeText("   multiple   \n\t spaces   here  "), "multiple spaces here");
  assert.equal(normalizeText(null), "");
});

test("tampered fingerprint prefix yields recomputed-mismatch and is skipped from publishing", () => {
  const [finding] = parseFixture("voicebox-qa-station-delta.md", "qa-station").findings;
  const tampered = { ...finding, fingerprintFromReport: "0".repeat(16), identitySource: "recomputed-mismatch" };
  const verdict = routeFinding(tampered);
  assert.equal(verdict.action, "skip");
  assert.match(verdict.reasons[0], /identity mismatch/);
});

// ---------------------------------------------------------------------------------------------
// 3. Severity mapping: fail-closed, identity before model label
// ---------------------------------------------------------------------------------------------

test("parseBadge parses single severity, routed elevation, and false positive", () => {
  assert.deepEqual(parseBadge("MEDIUM"), { reported: "medium" });
  assert.deepEqual(parseBadge("HIGH · routed critical"), { reported: "high", routed: "critical" });
  assert.deepEqual(parseBadge("FALSE POSITIVE"), { falsePositive: true });
});

test("severity is fail-closed: unrecognized or missing badge in fixture parses as critical", () => {
  const fixtureText = fixture("voicebox-qa-station-delta.md");
  for (const badge of ["SEVERE", "MEDUM", "5", "IMPORTANT", "UNKNOWN"]) {
    const rewritten = fixtureText.replace("[MEDIUM]", `[${badge}]`);
    assert.notEqual(rewritten, fixtureText, "badge replacement must occur");
    const [finding] = parseReport(rewritten, { agent: "qa-station" }).findings;
    assert.equal(finding.severityReported, badge.toLowerCase());
    assert.equal(
      finding.effectiveSeverity,
      "critical",
      `badge "${badge}" must fail closed to critical, got ${finding.effectiveSeverity}`,
    );
  }
});

test("an identity-critical station elevates a plain [MEDIUM] badge to critical without routed badge", () => {
  const rewritten = fixture("voicebox-secret-scan-delta.md").replace("[MEDIUM · routed critical]", "[MEDIUM]");
  assert.match(rewritten, /\[MEDIUM\]/);
  const [finding] = parseReport(rewritten, { agent: "secret-scan" }).findings;
  assert.equal(finding.severityReported, "medium");
  assert.equal(finding.severityRouted, null);
  assert.equal(finding.identityCritical, true);
  assert.equal(finding.effectiveSeverity, "critical", "secret-scan must be critical even on a plain MEDIUM label");
  const verdict = routeFinding(finding);
  assert.equal(verdict.action, "issue");
  assert.match(verdict.reasons[0], /identity-critical station `secret-scan`: routed critical/);
});

// ---------------------------------------------------------------------------------------------
// 4. Sanitisation: credential shapes masked, candidate withheld, published text clean
// ---------------------------------------------------------------------------------------------

test("every credential shape the factory masks is masked at runtime", () => {
  // Built at runtime — no realistic token is ever committed to repository
  const shapes = [
    ["pem-block", `-----BEGIN PRIVATE KEY-----\nMII${"A".repeat(64)}\n-----END PRIVATE KEY-----`],
    ["openai-key", `sk-${"B".repeat(24)}`],
    ["openai-key-proj", `sk-proj-${"C".repeat(24)}`],
    ["stripe-key", `sk_live_${"D".repeat(24)}`],
    ["google-api-key", `AIza${"E".repeat(35)}`],
    ["google-oauth", `ya29.${"F".repeat(25)}`],
    ["gitlab-pat", `glpat-${"G".repeat(20)}`],
    ["npm-token", `npm_${"H".repeat(36)}`],
    ["private-key", `-----BEGIN RSA PRIVATE KEY-----`],
    ["aws-access-key", `AKIA1234567890ABCDEF`],
    ["github-pat", `ghp_${"I".repeat(36)}`],
    ["github-pat-fine", `github_pat_${"J".repeat(22)}_${"K".repeat(59)}`],
    ["slack-token", `xoxb-12345678901-123456789012-${"L".repeat(24)}`],
    ["generic-api-key", `api_key = "${"M".repeat(32)}"`],
    ["jwt-token", `ey${"N".repeat(15)}.ey${"O".repeat(15)}.${"P".repeat(15)}`],
  ];

  for (const [name, token] of shapes) {
    const masked = maskText(`header ${token} footer`);
    assert.ok(!masked.includes(token), `${name} survived masking: ${masked}`);
    assert.match(masked, /\[redacted:[a-z-]+\]/);
  }
});

test("canary credential echoed into description or remediation is masked", () => {
  const [finding] = parseFixture("voicebox-qa-station-delta.md", "qa-station").findings;
  const canary = `sk-${"Z".repeat(24)}`;
  const withEcho = {
    ...finding,
    description: `model echoed raw token: ${canary} in analysis`,
    remediation: `rotate ${canary} immediately`,
  };
  const sanitized = sanitizeFinding(withEcho);
  assert.ok(!sanitized.description.includes(canary));
  assert.ok(sanitized.description.includes("[redacted:openai-key]"));
  assert.ok(!sanitized.remediation.includes(canary));
  assert.ok(sanitized.remediation.includes("[redacted:openai-key]"));
});

test("identity-critical station snippet is withheld wholesale for secret-scan and vuln-discovery", () => {
  const [secretFinding] = parseFixture("voicebox-secret-scan-delta.md", "secret-scan").findings;
  const secretSanitized = sanitizeFinding(secretFinding);
  assert.ok(secretSanitized.snippet.startsWith("[withheld: matched value not published"));
  assert.ok(!secretSanitized.snippet.includes("CANARY-fixture-not-a-real-credential"));

  const vulnFinding = {
    agent: "vuln-discovery",
    ruleId: "sqli-probe",
    path: "server/db.ts",
    lineNumber: "44",
    snippet: "' OR '1'='1' -- attack payload",
  };
  const vulnSanitized = sanitizeFinding(vulnFinding);
  assert.ok(vulnSanitized.snippet.startsWith("[withheld: matched value not published"));
  assert.ok(!vulnSanitized.snippet.includes("' OR '1'='1'"));
});

test("home paths and private root directory are elided from finding fields", () => {
  const [finding] = parseFixture("voicebox-qa-station-delta.md", "qa-station").findings;
  const rooted = {
    ...finding,
    description: "read from /home/operator/.voicebox/factory-reports/delta.md and /Users/developer/voicebox/x",
    remediation: "check /home/operator/.voicebox/factory-reports",
    path: "/home/operator/.voicebox/factory-reports/delta.md",
  };
  const sanitized = sanitizeFinding(rooted, { privateRoot: "/home/operator/.voicebox/factory-reports" });
  assert.ok(!sanitized.description.includes("/home/operator"));
  assert.ok(!sanitized.description.includes("/Users/developer"));
  assert.ok(sanitized.description.includes("<private-report-dir>"));
  assert.ok(sanitized.remediation.includes("<private-report-dir>"));
  assert.ok(sanitized.path.includes("<private-report-dir>"));
});

test("steering 1 (title elision): issue.title is built from sanitised title, eliding homedir and privateRoot", () => {
  const [qaFinding] = parseFixture("voicebox-qa-station-delta.md", "qa-station").findings;
  const privateRoot = "/tmp/secret-private-reports";
  const userHome = homedir();
  const findingWithHomeInTitle = {
    ...qaFinding,
    title: `chip assertion at ${userHome}/voicebox and ${privateRoot}/report-delta.md`,
  };
  const verdict = routeFinding(findingWithHomeInTitle);
  const issue = buildIssue(findingWithHomeInTitle, verdict, { privateRoot, repo: "owner/voicebox" });

  assert.ok(
    !issue.title.includes(userHome),
    `issue.title leaked home directory: ${issue.title}`,
  );
  assert.ok(
    !issue.title.includes(privateRoot),
    `issue.title leaked privateRoot: ${issue.title}`,
  );
  assert.ok(issue.title.includes("~"), `issue.title should contain ~ replacement: ${issue.title}`);
  assert.ok(
    issue.title.includes("<private-report-dir>"),
    `issue.title should contain <private-report-dir>: ${issue.title}`,
  );
});

test("steering 2 (credential-rule withholding): non-credential station with credential rule id withholds values", () => {
  for (const hint of CREDENTIAL_RULE_HINTS) {
    const finding = { agent: "qa-station", ruleId: `test-${hint}-finding` };
    assert.equal(isCredentialFinding(finding), true, `ruleId containing "${hint}" must be a credential finding`);
  }

  // qa-station is not a credential station, but rule id contains "password"
  const passwordSecret = "MyVerySecretPassword_XYZ_987";
  const nonCredFinding = {
    agent: "qa-station",
    ruleId: "hardcoded-password",
    path: "src/auth/login.ts",
    lineNumber: "12",
    state: "new",
    title: `echoed ${passwordSecret} in title`,
    description: `model found ${passwordSecret} in db connection`,
    remediation: `rotate password ${passwordSecret}`,
    snippet: `const pwd = "${passwordSecret}";`,
    className: "quality",
    effectiveSeverity: "high",
    severityReported: "high",
    identityCritical: false,
    fingerprint: "1".repeat(64),
    identitySource: "recomputed-and-verified",
  };

  const verdict = routeFinding(nonCredFinding);
  const issue = buildIssue(nonCredFinding, verdict, { repo: "owner/voicebox" });

  // Assert secret string is present NOWHERE in published issue title or body
  assert.ok(!issue.title.includes(passwordSecret), "secret leaked into issue title");
  assert.ok(!issue.body.includes(passwordSecret), "secret leaked into issue body");
  assert.ok(issue.body.includes(WITHHELD_NOTE), "body must include WITHHELD_NOTE");
  assert.ok(issue.body.includes(GENERIC_REMEDIATION), "body must include GENERIC_REMEDIATION");
});

test("steering 3 (derived text for credential findings): secret-scan publishes ONLY derived facts, no triage model prose", () => {
  const secretValue = "MyDatabasePassword_999";
  const secretFinding = {
    agent: "secret-scan",
    ruleId: "generic-api-key",
    path: "config/database.env",
    lineNumber: "25",
    state: "new",
    title: `Triage notes with ${secretValue}`,
    description: `The triage model noted ${secretValue} in prose`,
    remediation: `Change ${secretValue} to environment variable`,
    snippet: `DB_PASSWORD="${secretValue}"`,
    className: "security",
    effectiveSeverity: "critical",
    severityReported: "critical",
    identityCritical: true,
    fingerprint: "2".repeat(64),
    identitySource: "recomputed-and-verified",
  };

  const verdict = routeFinding(secretFinding);
  const issue = buildIssue(secretFinding, verdict, { repo: "owner/voicebox" });

  // Non-pattern secret string must appear NOWHERE in title or body
  assert.ok(!issue.title.includes(secretValue), `secretValue found in issue.title: ${issue.title}`);
  assert.ok(!issue.body.includes(secretValue), `secretValue found in issue.body: ${issue.body}`);

  // Derived facts must appear
  assert.match(issue.title, /generic-api-key match at config\/database\.env:25/);
  assert.ok(issue.body.includes(GENERIC_REMEDIATION));
  assert.ok(issue.body.includes(WITHHELD_NOTE));
  assert.match(issue.body, /The deterministic scanner matched `generic-api-key` at `config\/database\.env:25`/);
});

