test("file-issues skips creating issue when open issue already tracks the fingerprint", () => {
  const fp = computeFingerprint({
    agent: "qa-station",
    ruleId: "flake-instrumentation",
    path: "tests/room-folders.test.mjs",
    snippet: 'await page.waitForSelector("text=Projects")',
  });
  const stubGh = `case "$1" in
    issue)
      case "$2" in
        list) echo '[{"number": 42, "state": "OPEN", "body": "<!-- factory-fingerprint: ${fp} -->"}]' ;;
        create) echo "SHOULD_NOT_BE_CALLED" >&2; exit 1 ;;
        *) exit 1 ;;
      esac
      ;;
    label) echo '[]' ;;
  esac`;
  const res = runCli({
    args: ["--file-issues", "--report", "voicebox-qa-station-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-qa-station-delta.md": fixture("voicebox-qa-station-delta.md") },
    stubGh,
  });
  try {
    assert.equal(res.status, 2, `expected exit code 2 when all duplicate: ${res.stdout}\n${res.stderr}`);
    assert.equal(res.ghCalls.some((c) => c.startsWith("issue create")), false, "duplicate issue was created");
    assert.match(res.stdout, /duplicate: [0-9a-f]{16} \(an open issue already tracks it: #42\) — skipped/);
    assert.match(res.stdout, /issues: 0 published, 1 duplicate/);
  } finally {
    rmSync(res.box, { recursive: true, force: true });
  }
});

