test("isIssueDuplicate unit logic distinguishes open, closed-new, and closed-regressed", () => {
  const fp = "a".repeat(64);
  const openMap = new Map([[fp, [{ number: "12", state: "OPEN" }]]]);
  assert.equal(isIssueDuplicate({ fingerprint: fp, state: "new" }, openMap).numbers[0], "12");
  assert.equal(isIssueDuplicate({ fingerprint: fp, state: "regressed" }, openMap).why, "an open issue already tracks it");

  const closedMap = new Map([[fp, [{ number: "18", state: "CLOSED" }]]]);
  assert.equal(isIssueDuplicate({ fingerprint: fp, state: "new" }, closedMap).numbers[0], "18");
  assert.equal(isIssueDuplicate({ fingerprint: fp, state: "regressed" }, closedMap), null);

  const emptyMap = new Map();
  assert.equal(isIssueDuplicate({ fingerprint: fp, state: "new" }, emptyMap), null);
});

