test("no bead from a scan: script contains no automatic bead creation in scan paths", () => {
  const source = readFileSync(SCRIPT, "utf8");
  const bdCreateMatches = [...source.matchAll(/spawnSync\(\s*["']bd["'],\s*\[\s*["']create["']/g)];
  assert.equal(bdCreateMatches.length, 1, "bd create should only be called in one place in the script (promote)");
  const promoteIndex = source.indexOf("function promote(");
  assert.ok(promoteIndex > 0, "function promote exists");
  assert.ok(bdCreateMatches[0].index > promoteIndex, "bd create is inside promote");
  const mainIndex = source.indexOf("function main(");
  assert.ok(bdCreateMatches[0].index < mainIndex, "bd create is before main");
});

