/** A `gh` stub whose `issue view` prints `issueJson` (the file's existing stub style). */
const ghStubViewing = (issueJson) => `case "$1" in
  issue)
    case "$2" in
      view) cat << 'EOF'
${issueJson}
EOF
        ;;
      comment) echo "https://github.com/owner/voicebox/issues/10#issuecomment-2" ;;
      list) echo '[]' ;;
      *) echo "unknown issue subcmd: $2" >&2; exit 1 ;;
    esac
    ;;
  label) echo '[{"name":"bug"},{"name":"enhancement"},{"name":"documentation"},{"name":"human-review"}]' ;;
  *) echo "unknown gh cmd: $1" >&2; exit 1 ;;
esac`;

