test("agentFromReportName derives station via longest known suffix, never greedy hyphen split", () => {
  assert.equal(agentFromReportName("voicebox-docs-drift-delta.md"), "docs-drift");
  assert.equal(agentFromReportName("voicebox-vuln-discovery-delta.md"), "vuln-discovery");
  assert.equal(agentFromReportName("voicebox-deps-supply-chain-delta.md"), "deps-supply-chain");
  assert.equal(agentFromReportName("voicebox-threat-model-delta.md"), "threat-model");
  assert.equal(agentFromReportName("voicebox-qa-station-delta.md"), "qa-station");
  assert.equal(agentFromReportName("reports/docs-drift-delta.md"), "docs-drift");
  assert.equal(agentFromReportName("voicebox-delta.md"), null);
  assert.equal(agentFromReportName("random.md"), null);
});

test("unknown station is refused with exit 1 unless --agent overrides it", () => {
  const unknown = runCli({
    args: ["--report", "voicebox-not-a-station-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-not-a-station-delta.md": fixture("voicebox-qa-station-delta.md") },
  });
  try {
    assert.equal(unknown.status, 1);
    assert.match(unknown.stderr, /cannot determine the station; pass --agent/);
  } finally {
    rmSync(unknown.box, { recursive: true, force: true });
  }

  const invalidOverride = runCli({
    args: ["--agent", "not-a-real-station", "--report", "voicebox-qa-station-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-qa-station-delta.md": fixture("voicebox-qa-station-delta.md") },
  });
  try {
    assert.equal(invalidOverride.status, 1);
    assert.match(invalidOverride.stderr, /unknown station "not-a-real-station"/);
  } finally {
    rmSync(invalidOverride.box, { recursive: true, force: true });
  }

  const validOverride = runCli({
    args: ["--agent", "qa-station", "--report", "voicebox-custom-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-custom-delta.md": fixture("voicebox-qa-station-delta.md") },
  });
  try {
    assert.equal(validOverride.status, 0, validOverride.stderr);
  } finally {
    rmSync(validOverride.box, { recursive: true, force: true });
  }
});

