test("low and info findings are skipped by default and published with --include-low", () => {
  const [lowFinding] = parseFixture("voicebox-modern-web-delta.md", "modern-web").findings;
  assert.equal(lowFinding.effectiveSeverity, "low");
  assert.equal(routeFinding(lowFinding).action, "skip");
  assert.match(routeFinding(lowFinding).reasons[0], /low is below the published band/);
  assert.equal(routeFinding(lowFinding, { includeLow: true }).action, "issue");

  const infoFinding = { ...lowFinding, effectiveSeverity: "info" };
  assert.equal(routeFinding(infoFinding).action, "skip");
  assert.equal(routeFinding(infoFinding, { includeLow: true }).action, "issue");

  const skipRun = runCli({
    args: ["--report", "voicebox-modern-web-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-modern-web-delta.md": fixture("voicebox-modern-web-delta.md") },
  });
  try {
    assert.equal(skipRun.status, 2, "nothing actionable without --include-low");
    assert.match(skipRun.stdout, /NOT PUBLISHED/);
  } finally {
    rmSync(skipRun.box, { recursive: true, force: true });
  }

  const includeRun = runCli({
    args: ["--report", "voicebox-modern-web-delta.md", "--include-low", "--repo", "owner/voicebox"],
    reports: { "voicebox-modern-web-delta.md": fixture("voicebox-modern-web-delta.md") },
  });
  try {
    assert.equal(includeRun.status, 0, includeRun.stderr);
    assert.match(includeRun.stdout, /PUBLISH ISSUE.*P3 low modern-web/);
  } finally {
    rmSync(includeRun.box, { recursive: true, force: true });
  }
});

test("reduced-form finding without snippet has unverifiable identity and is not published", () => {
  const [reducedFinding] = parseFixture("voicebox-vuln-discovery-delta.md", "vuln-discovery").findings;
  assert.equal(reducedFinding.identitySource, "unverifiable");
  assert.equal(reducedFinding.fingerprint, null);
  assert.equal(reducedFinding.ruleId, "path-traversal", "rule id parsed from heading in reduced form");
  assert.equal(reducedFinding.effectiveSeverity, "critical", "vuln-discovery is identity-critical");
  const verdict = routeFinding(reducedFinding);
  assert.equal(verdict.action, "skip");
  assert.match(verdict.reasons[0], /identity unverifiable: the report carried no recomputable fingerprint/);

  const res = runCli({
    args: ["--report", "voicebox-vuln-discovery-delta.md", "--repo", "owner/voicebox"],
    reports: { "voicebox-vuln-discovery-delta.md": fixture("voicebox-vuln-discovery-delta.md") },
  });
  try {
    assert.equal(res.status, 2, "unverifiable finding should yield nothing actionable");
    assert.match(res.stdout, /NOT PUBLISHED.*vuln-discovery path-traversal/);
  } finally {
    rmSync(res.box, { recursive: true, force: true });
  }
});

