test("buildPlan over ALL fixtures at once yields expected per-finding action map", () => {
  const names = readdirSync(FIXTURES).filter((n) => n.endsWith("-delta.md"));
  const files = names.map((n) => join(FIXTURES, n));
  const plan = buildPlan(files, {
    privateRoot: "/private",
    includeLow: false,
    functionality: new Set(),
    repo: "owner/voicebox",
  });

  const byAgentRule = Object.fromEntries(
    plan.map((entry) => [`${entry.finding.agent}:${entry.finding.ruleId}`, entry.verdict.action]),
  );

  assert.equal(byAgentRule["qa-station:flake-instrumentation"], "issue");
  assert.equal(byAgentRule["secret-scan:generic-api-key"], "issue", "embargo bypass: secret-scan finding is published as issue");
  assert.equal(byAgentRule["perf-review:blocking-boot-probe"], "issue");
  assert.equal(byAgentRule["docs-drift:stale-route-table"], "issue");
  assert.equal(byAgentRule["modern-web:legacy-light-dismiss"], "skip", "low severity skipped by default");
  assert.equal(byAgentRule["vuln-discovery:path-traversal"], "skip", "unverifiable identity skipped");

  // With includeLow: true
  const planWithLow = buildPlan(files, {
    privateRoot: "/private",
    includeLow: true,
    functionality: new Set(),
    repo: "owner/voicebox",
  });
  const byAgentRuleLow = Object.fromEntries(
    planWithLow.map((entry) => [`${entry.finding.agent}:${entry.finding.ruleId}`, entry.verdict.action]),
  );
  assert.equal(byAgentRuleLow["modern-web:legacy-light-dismiss"], "issue");

  // With functionality change confirmed
  const planWithFunc = buildPlan(files, {
    privateRoot: "/private",
    includeLow: false,
    functionality: new Set(["flake-instrumentation"]),
    repo: "owner/voicebox",
  });
  const qaEntry = planWithFunc.find((e) => e.finding.agent === "qa-station");
  assert.equal(qaEntry.verdict.action, "issue");
  assert.equal(qaEntry.verdict.humanReview, true);
  assert.match(qaEntry.issue.title, /^\[human-review\]/);
});

